class Solution {
public:
    int minSteps(string s, string t) {
        vector<int> cnt(26, 0);
        for (char ch : s) cnt[ch - 'a']++;
        for (char ch : t) cnt[ch - 'a']--;
        int ans = 0;
        for (int x : cnt) ans += abs(x);
        return ans;
    }
};

class Solution {
    public int minSteps(String s, String t) {
        int[] cnt = new int[26];
        for (char ch : s.toCharArray()) cnt[ch - 'a']++;
        for (char ch : t.toCharArray()) cnt[ch - 'a']--;
        int ans = 0;
        for (int x : cnt) ans += Math.abs(x);
        return ans;
    }
}

var minSteps = function(s, t) {
    const cnt = new Int32Array(26);
    for (let i = 0; i < s.length; i++) cnt[s.charCodeAt(i) - 97]++;
    for (let i = 0; i < t.length; i++) cnt[t.charCodeAt(i) - 97]--;
    let ans = 0;
    for (let i = 0; i < 26; i++) ans += Math.abs(cnt[i]);
    return ans;
};
